static bool g_tr = false;   // the wizard's own language: Turkish, else English

static const wchar_t* Tx(const wchar_t* tr, const wchar_t* en) { return g_tr ? tr : en; }

static std::wstring SizeText(double bytes)
{
    wchar_t buf[64];
    if (bytes >= 1073741824.0) swprintf(buf, 64, L"%.1f GB", bytes / 1073741824.0);
    else if (bytes >= 10485760.0) swprintf(buf, 64, L"%.0f MB", bytes / 1048576.0);
    else if (bytes >= 1048576.0) swprintf(buf, 64, L"%.1f MB", bytes / 1048576.0);
    else swprintf(buf, 64, L"%.0f KB", bytes / 1024.0);
    std::wstring s = buf;
    if (g_tr) std::replace(s.begin(), s.end(), L'.', L',');
    return s;
}

